insert into public.issue_types (id, label, label_hi, agency, owns, channels, ladder, role_ids, sort, filing) values
  ('roads', 'Roads, footpaths', 'सड़क, फ़ुटपाथ', 'GMDA for master roads, MCG for internal roads', 'GMDA owns the master roads between sectors and the major corridors. MCG owns internal roads, lanes and footpaths. HSVP keeps its own sectors until transfer; developers keep licensed colonies under DTCP. NH-48 and the expressways are NHAI.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"},{"k":"Highways","v":"NHAI 1033","href":"tel:1033","ic":"phone"}]'::jsonb, '["Ticket on the portal; keep the number. Only you can close it.","No action in time: the officer named on the ticket, then the zone Joint Commissioner or Executive Engineer.","Still pending: MCG Commissioner and Mayor, or GMDA CEO.","Final: CM Window, with every ticket number attached."]'::jsonb, array['gmda','mcg','hsvp','dtcp','nhai','councillor','je']::text[], 0, '{"portal":"GMDA integrated grievance portal","url":"https://services.gmda.gov.in/","note":"The portal asks for the exact location and a photo; the ticket number comes back by SMS.","fields":[{"k":"landmark","l":"Nearest landmark or house number","t":"text","r":true},{"k":"road","l":"Road or street name","t":"text"},{"k":"nature","l":"What exactly","t":"select","r":true,"o":["Pothole","Broken footpath","Road caved in","Unfinished work","Encroachment on road","Other"]},{"k":"since","l":"Since when","t":"date"}],"docs":[{"k":"photo","l":"Photo of the spot","t":"photo","r":true},{"k":"photo_wide","l":"Wider photo showing the road","t":"photo"}]}'::jsonb),
  ('waste', 'Garbage', 'कचरा', 'MCG sanitation wing', 'Door-to-door collection, sweeping, collection points, bulk waste and debris. Societies producing 100 kg a day or more must process wet waste on site under the 2016 rules.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"},{"k":"Central record","v":"Swachhata app","href":"https://swachhbharaturban.gov.in/","ic":"app"}]'::jsonb, '["Ticket on the portal or the Swachhata app; keep the number.","Not attended: the ward sanitary inspector, then the zone Joint Commissioner.","Still pending: MCG Commissioner and Mayor.","Final: CM Window with the ticket history."]'::jsonb, array['mcg','ulb','mohua','councillor','je','rwa']::text[], 1, '{"portal":"GMDA integrated grievance portal or Swachhata app","url":"https://services.gmda.gov.in/","note":"A geo-tagged photo routes the complaint to the ward''s sanitation inspector.","fields":[{"k":"where","l":"Type of place","t":"select","r":true,"o":["Street or lane","Collection point","Park","Drain","Vacant plot","Society gate","Market"]},{"k":"since","l":"Since when","t":"date"},{"k":"frequency","l":"How often","t":"select","o":["Today only","A few days","Every week","Always"]}],"docs":[{"k":"photo","l":"Photo of the garbage","t":"photo","r":true}]}'::jsonb),
  ('water', 'Water, sewer', 'पानी, सीवर', 'GMDA for bulk supply, MCG for distribution', 'GMDA runs the treatment plants, master water lines and master sewers. MCG owns distribution and internal sewers inside sectors; HSVP in its own sectors. Tankers during a shortage come through the same ticket.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"}]'::jsonb, '["Ticket on the portal; keep the number. Only you can close it.","No action in time: the officer named on the ticket, then the zone Joint Commissioner or Executive Engineer.","Still pending: MCG Commissioner and Mayor, or GMDA CEO.","Final: CM Window, with every ticket number attached."]'::jsonb, array['gmda','mcg','hsvp','je']::text[], 2, '{"portal":"GMDA integrated grievance portal","url":"https://services.gmda.gov.in/","note":"Quote the connection or bill number if there is one; it speeds up the search for the line.","fields":[{"k":"nature","l":"What exactly","t":"select","r":true,"o":["No supply","Low pressure","Dirty or smelly water","Sewer overflow","Leak on the road","Illegal connection"]},{"k":"connection","l":"Water connection or bill number","t":"text","h":"On the water bill, if any"},{"k":"since","l":"Since when","t":"date","r":true},{"k":"houses","l":"Houses affected (about)","t":"number"}],"docs":[{"k":"photo","l":"Photo (leak, overflow or dirty water)","t":"photo"},{"k":"bill","l":"Water bill","t":"any"}]}'::jsonb),
  ('drains', 'Drains, flooding', 'नाले, जलभराव', 'GMDA for master drains, MCG for internal drains', 'GMDA owns the master storm drains and natural creeks. MCG owns internal drains, desilting and road gullies. In the monsoon the district control room coordinates emergency pumping.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"},{"k":"District","v":"Control room and helplines","href":"https://gurugram.gov.in/helpline/","ic":"phone"}]'::jsonb, '["Ticket on the portal; keep the number. Only you can close it.","No action in time: the officer named on the ticket, then the zone Joint Commissioner or Executive Engineer.","Still pending: MCG Commissioner and Mayor, or GMDA CEO.","Final: CM Window, with every ticket number attached."]'::jsonb, array['gmda','mcg','dc','je']::text[], 3, '{"portal":"GMDA integrated grievance portal","url":"https://services.gmda.gov.in/","note":"During the monsoon also call the district control room; the ticket still goes on the portal.","fields":[{"k":"nature","l":"What exactly","t":"select","r":true,"o":["Blocked drain","Overflowing drain","Waterlogging","Broken or missing cover","Drain needs desilting"]},{"k":"landmark","l":"Nearest landmark","t":"text","r":true},{"k":"since","l":"Since when","t":"date"}],"docs":[{"k":"photo","l":"Photo of the drain or flooding","t":"photo","r":true}]}'::jsonb),
  ('lights', 'Streetlights', 'स्ट्रीट लाइट', 'MCG for internal roads, GMDA for master roads', 'Dark stretches, faulty poles and timers on internal roads are MCG; on sector-dividing and master roads they are GMDA. Quote the pole number if it is painted on.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"}]'::jsonb, '["Ticket on the portal; keep the number. Only you can close it.","No action in time: the officer named on the ticket, then the zone Joint Commissioner or Executive Engineer.","Still pending: MCG Commissioner and Mayor, or GMDA CEO.","Final: CM Window, with every ticket number attached."]'::jsonb, array['mcg','gmda','je']::text[], 4, '{"portal":"GMDA integrated grievance portal","url":"https://services.gmda.gov.in/","note":"The pole number painted on the pole is the fastest way to the right light.","fields":[{"k":"pole","l":"Pole number","t":"text","h":"Painted on the pole, if visible"},{"k":"stretch","l":"Stretch or lane","t":"text","r":true},{"k":"count","l":"How many lights","t":"number"},{"k":"nature","l":"What exactly","t":"select","o":["Not working","Flickering","On in daytime","Pole damaged","Wire hanging"]}],"docs":[{"k":"photo","l":"Photo (night photo helps)","t":"photo"}]}'::jsonb),
  ('parks', 'Parks, trees', 'पार्क, पेड़', 'MCG horticulture; HSVP in its sectors; Forest Department for trees', 'Neighbourhood parks are MCG horticulture. Green belts along HSVP roads are HSVP. Felling or damaging a tree needs Forest Department permission; report illegal felling to the Forest Department and the police.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"}]'::jsonb, '["Ticket on the portal; keep the number. Only you can close it.","No action in time: the officer named on the ticket, then the zone Joint Commissioner or Executive Engineer.","Still pending: MCG Commissioner and Mayor, or GMDA CEO.","Final: CM Window, with every ticket number attached."]'::jsonb, array['mcg','hsvp']::text[], 5, '{"portal":"GMDA integrated grievance portal","url":"https://services.gmda.gov.in/","note":"Tree cutting also goes to the Forest Department; keep the photos.","fields":[{"k":"park","l":"Park or green belt name","t":"text","r":true},{"k":"nature","l":"What exactly","t":"select","r":true,"o":["Not maintained","Broken equipment","Encroachment","Tree cutting","Dead tree or fallen branch","No water"]}],"docs":[{"k":"photo","l":"Photo","t":"photo","r":true}]}'::jsonb),
  ('traffic', 'Traffic', 'ट्रैफ़िक', 'Gurugram Traffic Police; GMDA for signals', 'Enforcement, wrong-side driving and parking are the Traffic Police. Faulty signals, signage and junction design are GMDA. Vendors and structures on roads are MCG enforcement.', '[{"k":"Emergency","v":"112","href":"tel:112","ic":"phone"},{"k":"Police","v":"Haryana Police portal","href":"https://haryanapolice.gov.in/","ic":"link"},{"k":"Signals","v":"GMDA integrated portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"}]'::jsonb, '["Traffic Police for enforcement; a GMDA ticket for signals and engineering.","Not attended: the ACP Traffic of the zone, then the DCP Traffic.","Still pending: the Commissioner of Police, Gurugram.","Final: CM Window, or a Forum policy dialogue for a recurring junction."]'::jsonb, array['police','gmda','mcg']::text[], 6, '{"portal":"Gurugram Traffic Police; GMDA for signals","url":"https://haryanapolice.gov.in/","note":"For a violation the police need the vehicle number, time and a photo or video.","fields":[{"k":"nature","l":"What exactly","t":"select","r":true,"o":["Wrong-side driving","Signal not working","Illegal parking","Encroachment on road","Speeding","No signage","Other"]},{"k":"vehicle","l":"Vehicle number (if a violation)","t":"text"},{"k":"when","l":"Date and time","t":"datetime","r":true},{"k":"junction","l":"Junction or stretch","t":"text","r":true}],"docs":[{"k":"photo","l":"Photo or video still","t":"photo"}]}'::jsonb),
  ('power', 'Electricity', 'बिजली', 'DHBVN', 'Outages, tripping, broken poles, meter faults and billing disputes. Restoration and meter timelines are set by the Haryana Electricity Regulatory Commission.', '[{"k":"Helpline","v":"1912","href":"tel:1912","ic":"phone"},{"k":"Portal","v":"DHBVN consumer portal","href":"https://dhbvn.org.in/","ic":"link"}]'::jsonb, '["Register on 1912 or the portal; keep the complaint number.","Not resolved: the SDO (Operation), then the Executive Engineer.","Still pending: the Consumer Grievance Redressal Forum, DHBVN.","Final: the Electricity Ombudsman, Haryana."]'::jsonb, array['dhbvn']::text[], 7, '{"portal":"DHBVN 1912 and consumer portal","url":"https://dhbvn.org.in/","note":"DHBVN registers a complaint against the account number on the bill, not the address alone.","fields":[{"k":"account","l":"DHBVN account number (K number)","t":"text","r":true,"h":"On the electricity bill"},{"k":"meter","l":"Meter number","t":"text"},{"k":"nature","l":"What exactly","t":"select","r":true,"o":["No supply","Frequent tripping","Low voltage","Meter faulty","Billing wrong","Broken pole or hanging wire","Transformer problem"]},{"k":"since","l":"Since when","t":"datetime"}],"docs":[{"k":"bill","l":"Latest electricity bill","t":"any"},{"k":"photo","l":"Photo (pole, wire or meter)","t":"photo"}]}'::jsonb),
  ('pollution', 'Air, noise', 'हवा, शोर', 'HSPCB regional office, Gurugram', 'Construction dust, industrial emissions, noise and waste burning. Burning on public land is also MCG. Under GRAP, the Commission for Air Quality Management sets NCR-wide restrictions.', '[{"k":"Central app","v":"Sameer (CPCB)","href":"https://cpcb.nic.in/","ic":"app"},{"k":"State board","v":"HSPCB","href":"https://hspcb.gov.in/","ic":"link"},{"k":"Portal","v":"GMDA portal, air-monitoring cell","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"}]'::jsonb, '["Complaint on Sameer or the GMDA portal, with photo and time.","Not attended: the HSPCB Regional Officer, Gurugram.","Still pending: Member Secretary, HSPCB, and the Deputy Commissioner.","Final: CM Window, or CPGRAMS for CPCB and CAQM."]'::jsonb, array['hspcb','caqm','mcg','dc']::text[], 8, '{"portal":"HSPCB regional office; Sameer app for air","url":"https://hspcb.gov.in/","note":"Name the source and the time pattern; a dated photo or video is the evidence the board acts on.","fields":[{"k":"source","l":"Source","t":"select","r":true,"o":["Construction dust","Garbage or leaf burning","Industrial smoke","Generator or vehicle fumes","Noise (loudspeaker, construction, generator)","Water discharge or dumping"]},{"k":"who","l":"Site, unit or society responsible (if known)","t":"text"},{"k":"when","l":"When does it happen","t":"text","r":true,"h":"For example: every night after 10 pm"}],"docs":[{"k":"photo","l":"Photo or video still","t":"photo","r":true}]}'::jsonb),
  ('animals', 'Stray animals', 'आवारा पशु', 'MCG veterinary wing', 'Stray dog sterilisation and vaccination, stray cattle, carcass removal and dog-bite follow-up.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"}]'::jsonb, '["Ticket on the portal; keep the number. Only you can close it.","No action in time: the officer named on the ticket, then the zone Joint Commissioner or Executive Engineer.","Still pending: MCG Commissioner and Mayor, or GMDA CEO.","Final: CM Window, with every ticket number attached."]'::jsonb, array['mcg','je']::text[], 9, '{"portal":"GMDA integrated grievance portal","url":"https://services.gmda.gov.in/","note":"For a dog bite also note the hospital and date; MCG''s veterinary wing handles sterilisation and cattle.","fields":[{"k":"animal","l":"Which animals","t":"select","r":true,"o":["Stray dogs","Stray cattle","Monkeys","Pigs","Dead animal (carcass)"]},{"k":"count","l":"How many (about)","t":"number"},{"k":"aggressive","l":"Any bite or attack","t":"select","o":["No","Yes"]}],"docs":[{"k":"photo","l":"Photo","t":"photo"}]}'::jsonb),
  ('construction', 'Illegal construction', 'अवैध निर्माण', 'MCG town planning; DTCP for licensed colonies; HSVP in its sectors', 'Unauthorised floors, commercial use of residential plots and encroachment inside municipal limits are MCG. Licensed private colonies are the District Town Planner. HSVP sectors are the HSVP Estate Officer.', '[{"k":"Portal","v":"GMDA integrated grievance portal","href":"https://services.gmda.gov.in/","ic":"link"},{"k":"Toll-free","v":"1800 180 1817","href":"tel:18001801817","ic":"phone"},{"k":"WhatsApp","v":"78400 01817, with a photo","href":"https://wa.me/917840001817","ic":"chat"},{"k":"App","v":"myGurugram","ic":"app"},{"k":"DTCP","v":"Town and Country Planning","href":"https://tcpharyana.gov.in/","ic":"link"},{"k":"HSVP","v":"HSVP","href":"https://hsvphry.org.in/","ic":"link"}]'::jsonb, '["Written complaint with photos, plus a ticket on the portal.","Not attended: Senior Town Planner (MCG) or District Town Planner (DTCP).","Still pending: MCG Commissioner or Director, Town and Country Planning.","Final: CM Window."]'::jsonb, array['mcg','dtcp','hsvp']::text[], 10, '{"portal":"MCG town planning; DTCP for licensed colonies","url":"https://services.gmda.gov.in/","note":"A written complaint with photos and the exact property address is what the planning wing acts on.","fields":[{"k":"address","l":"Exact address of the property","t":"text","r":true},{"k":"nature","l":"What exactly","t":"select","r":true,"o":["Extra floor or unauthorised extension","Commercial use of residential plot","Encroachment on public land","Unsafe or dangerous building","Construction without permission"]},{"k":"owner","l":"Owner or builder, if known","t":"text"},{"k":"ongoing","l":"Is work going on now","t":"select","o":["Yes","No"]}],"docs":[{"k":"photo","l":"Photos of the construction","t":"photo","r":true}]}'::jsonb),
  ('property', 'Property tax', 'संपत्ति कर', 'MCG', 'Property-tax assessment and correction, building plans, occupation and no-dues certificates. Most are notified services with fixed time limits under the Right to Service Act.', '[{"k":"Portal","v":"ULB property tax and services","href":"https://ulbharyana.gov.in/","ic":"link"},{"k":"Services","v":"Saral Haryana","href":"https://saralharyana.gov.in/","ic":"link"},{"k":"MCG","v":"mcg.gov.in","href":"https://www.mcg.gov.in/","ic":"link"}]'::jsonb, '["Apply online; keep the application number.","Past the notified limit: the Auto Appeal System escalates for you.","Still pending: Grievance Officer, then the Right to Service Commission.","Parallel route: CM Window."]'::jsonb, array['mcg','ulb','rts']::text[], 11, '{"portal":"Haryana ULB property tax portal / MCG","url":"https://ulbharyana.gov.in/","note":"Every request is against the Property ID; a service with a notified time limit auto-escalates under the Right to Service Act.","fields":[{"k":"pid","l":"Property ID","t":"text","r":true,"h":"On the property tax receipt or notice"},{"k":"owner","l":"Owner name as per record","t":"text","r":true},{"k":"request","l":"What you need","t":"select","r":true,"o":["Correct the record (area, name, category)","Dues shown wrongly","No-dues certificate","Name transfer","Other"]},{"k":"earlier","l":"Earlier application or ticket number","t":"text"}],"docs":[{"k":"receipt","l":"Property tax receipt or notice","t":"any","r":true},{"k":"id","l":"ID proof of the owner","t":"any"},{"k":"ownership","l":"Sale deed or allotment letter","t":"pdf"}]}'::jsonb),
  ('housing', 'Builders, societies', 'बिल्डर, सोसाइटी', 'HRERA Gurugram; DTCP; District Registrar', 'Delayed possession and defects go to HRERA. Maintenance handover and licence conditions are DTCP. Disputes inside an RWA or AOA go to the District Registrar under the 2012 Act.', '[{"k":"HRERA","v":"HRERA Gurugram","href":"https://haryanarera.gov.in/","ic":"link"},{"k":"DTCP","v":"Town and Country Planning","href":"https://tcpharyana.gov.in/","ic":"link"},{"k":"District","v":"District Registrar, Firms and Societies","href":"https://gurugram.gov.in/","ic":"link"}]'::jsonb, '["File with HRERA or DTCP with the agreement and payment record.","HRERA: appeal to the Real Estate Appellate Tribunal.","DTCP: Director, Town and Country Planning, then CM Window.","Society-wide patterns go to a Forum policy dialogue."]'::jsonb, array['hrera','dtcp','dc']::text[], 12, '{"portal":"HRERA Gurugram","url":"https://haryanarera.gov.in/","note":"HRERA needs the project''s RERA registration, the builder-buyer agreement and proof of payment; a complaint is filed online with a fee.","fields":[{"k":"project","l":"Project name","t":"text","r":true},{"k":"builder","l":"Builder or promoter","t":"text","r":true},{"k":"rera","l":"RERA registration number of the project","t":"text","h":"On the agreement, brochure or the HRERA site"},{"k":"unit","l":"Unit or flat number","t":"text"},{"k":"booking","l":"Booking date","t":"date"},{"k":"paid","l":"Amount paid so far (rupees)","t":"number"},{"k":"possession","l":"Promised possession date","t":"date"},{"k":"relief","l":"What you want","t":"select","r":true,"o":["Possession or delay interest","Refund with interest","Defects fixed","Maintenance or handover to RWA","Society or RWA dispute"]}],"docs":[{"k":"agreement","l":"Builder-buyer agreement or allotment letter","t":"pdf","r":true},{"k":"receipts","l":"Payment receipts or bank statement","t":"any","r":true},{"k":"letters","l":"Correspondence with the builder","t":"any"},{"k":"id","l":"ID proof","t":"any"}]}'::jsonb),
  ('safety', 'Police, cyber', 'पुलिस, साइबर', 'Gurugram Police', 'Crime, harassment, threats, domestic violence and cyber fraud. Any station must register a Zero FIR for a cognisable offence; you get a free copy of the FIR.', '[{"k":"Emergency","v":"112","href":"tel:112","ic":"phone"},{"k":"Women","v":"181","href":"tel:181","ic":"phone"},{"k":"Cyber fraud","v":"1930, within the first hour","href":"tel:1930","ic":"phone"},{"k":"Portal","v":"cybercrime.gov.in","href":"https://cybercrime.gov.in/","ic":"link"},{"k":"Police","v":"Haryana Police","href":"https://haryanapolice.gov.in/","ic":"link"}]'::jsonb, '["112 in an emergency; otherwise the station or online.","FIR refused: written complaint to the DCP of the zone.","Still refused: Commissioner of Police, or the Judicial Magistrate.","Cyber fraud: 1930 first, then the portal, then the station."]'::jsonb, array['police']::text[], 13, '{"portal":"Gurugram Police; cybercrime.gov.in and 1930 for online fraud","url":"https://cybercrime.gov.in/","note":"For online fraud, call 1930 within the first hour to freeze the money; the portal then needs transaction details and screenshots.","fields":[{"k":"nature","l":"What happened","t":"select","r":true,"o":["Theft or burglary","Harassment or stalking","Threat or assault","Online or UPI fraud","Domestic violence","Missing person","Other"]},{"k":"when","l":"Date and time","t":"datetime","r":true},{"k":"place","l":"Where exactly","t":"text"},{"k":"amount","l":"Amount lost (rupees), if fraud","t":"number"},{"k":"platform","l":"Bank, UPI app or platform involved","t":"text"},{"k":"txn","l":"Transaction IDs, numbers or accounts involved","t":"textarea"}],"docs":[{"k":"screens","l":"Screenshots or photos","t":"photo"},{"k":"id","l":"ID proof","t":"any"},{"k":"bank","l":"Bank statement or payment proof","t":"any"}]}'::jsonb),
  ('consumer', 'Consumer', 'उपभोक्ता', 'National Consumer Helpline; District Commission, Gurugram', 'Defective goods, unfair charges, deficient services, online disputes. The District Commission hears claims up to 50 lakh rupees; the State Commission up to 2 crore.', '[{"k":"Helpline","v":"1915","href":"tel:1915","ic":"phone"},{"k":"Portal","v":"consumerhelpline.gov.in","href":"https://consumerhelpline.gov.in/","ic":"link"},{"k":"File online","v":"e-Jagriti","href":"https://e-jagriti.gov.in/","ic":"link"}]'::jsonb, '["Written complaint to the seller; keep the record.","No resolution: 1915 mediation with the company.","Still unresolved: District Commission, Gurugram, on e-Jagriti.","Appeal to the State Commission, Panchkula."]'::jsonb, array['consumer']::text[], 14, '{"portal":"National Consumer Helpline; e-Jagriti for the District Commission","url":"https://consumerhelpline.gov.in/","note":"Keep the invoice and the complaint you sent the seller; the helpline mediates first, e-Jagriti files the case.","fields":[{"k":"seller","l":"Seller, brand or service provider","t":"text","r":true},{"k":"order","l":"Order, invoice or policy number","t":"text"},{"k":"date","l":"Purchase date","t":"date","r":true},{"k":"amount","l":"Amount (rupees)","t":"number","r":true},{"k":"issue","l":"Issue","t":"select","r":true,"o":["Defective product","Not delivered","Refund not given","Overcharging","Service deficiency","Misleading claim"]},{"k":"sellerdate","l":"Date you complained to the seller","t":"date"}],"docs":[{"k":"invoice","l":"Invoice or payment proof","t":"any","r":true},{"k":"letters","l":"Emails or chats with the seller","t":"any"},{"k":"photo","l":"Photo of the product or defect","t":"photo"},{"k":"id","l":"ID proof","t":"any"}]}'::jsonb),
  ('rti', 'RTI', 'सूचना (RTI)', 'The Public Information Officer of that office', 'Any record a public authority holds: files, tenders, inspection reports, budgets. Reply due in 30 days, 48 hours where life or liberty is at stake.', '[{"k":"Central","v":"RTI Online","href":"https://rtionline.gov.in/","ic":"link"},{"k":"State","v":"PIO of MCG, GMDA, HSVP or DTCP, with a 10 rupee fee","ic":"mail"}]'::jsonb, '["Application to the PIO with the fee.","No reply in 30 days: first appeal in the same office.","Second appeal: State Information Commission (CIC for central bodies).","The Forum can help draft a precise request."]'::jsonb, '{}'::text[], 15, '{"portal":"RTI Online (central) or the office''s PIO (state)","url":"https://rtionline.gov.in/","note":"An RTI needs the exact public authority and precise questions; the fee is 10 rupees.","fields":[{"k":"authority","l":"Public authority (MCG, GMDA, HSVP, DTCP, a ministry)","t":"text","r":true},{"k":"questions","l":"Information sought, as numbered questions","t":"textarea","r":true},{"k":"period","l":"Period the information covers","t":"text"},{"k":"delivery","l":"How to receive it","t":"select","o":["Email","Post"]}],"docs":[{"k":"id","l":"ID proof (needed for BPL fee exemption only)","t":"any"},{"k":"earlier","l":"Earlier RTI or reply, if a repeat","t":"pdf"}]}'::jsonb),
  ('other', 'Something else', 'कुछ और', 'Depends on the subject; the Forum maps it', 'A scheme not reaching you, a service that needs redesign, an idea for the city. The Forum reads every submission and points it to a desk or a policy dialogue.', '[{"k":"State","v":"CM Window","href":"https://cmharyanacell.nic.in/","ic":"link"},{"k":"Central","v":"CPGRAMS","href":"https://pgportal.gov.in/","ic":"link"},{"k":"Forum","v":"Report it here","href":"#/report","ic":"chat"}]'::jsonb, '["Send it through the Forum.","A volunteer maps it within three working days.","Recurring themes go to a policy dialogue."]'::jsonb, array['cm','chapter']::text[], 16, '{"portal":"CM Window or CPGRAMS, depending on the subject","url":"https://cmharyanacell.nic.in/","note":"The Forum maps it first; CM Window needs an ID proof and a written complaint.","fields":[{"k":"dept","l":"Department you think is responsible","t":"text"},{"k":"earlier","l":"Earlier complaint numbers, if any","t":"text"}],"docs":[{"k":"any","l":"Any supporting document or photo","t":"any"},{"k":"id","l":"ID proof (CM Window asks for it)","t":"any"}]}'::jsonb)
